var REGIONS = {"marmara":{"name":{"it":"Marmara e Istanbul"},"tag":{"it":"Due continenti, tre imperi — e le mura di Troia"}},"aegean":{"name":{"it":"Costa egea"},"tag":{"it":"Città di marmo antiche, terrazze termali e porti imbiancati a calce"}},"med":{"name":{"it":"Mediterraneo — la Costa turchese"},"tag":{"it":"Lagune orlate di pini, rovine licie e 300 giorni di sole"}},"central":{"name":{"it":"Anatolia centrale"},"tag":{"it":"Camini delle fate, città sotterranee e patria dei dervisci rotanti"}},"north":{"name":{"it":"Mar Nero"},"tag":{"it":"Monasteri a strapiombo, giardini di tè e borghi ottomani intatti"}},"east":{"name":{"it":"Anatolia orientale"},"tag":{"it":"Altipiani, una capitale fantasma e un’isola-chiesa su un lago sodico"}},"southeast":{"name":{"it":"Anatolia sud-orientale"},"tag":{"it":"Mesopotamia: il primo tempio del mondo e città più antiche della storia"}}};
var D = [{"id":"hagia","img":"assets/hagia.jpg","region":"marmara","unesco":true,"name":{"it":"Santa Sofia"},"desc":{"it":"Costruita nel 537 come la più grande cattedrale di Bisanzio e poi moschea imperiale: per quasi mille anni è stato lo spazio coperto più ampio della Terra. La cupola dorata che sembra sospesa e la storia stratificata ne fanno l’edificio più celebre della Turchia."},"loc":{"it":"Sultanahmet, Istanbul"},"best":{"it":"Apr–giu e set–nov; arriva all’apertura"},"tip":{"it":"I visitatori stranieri percorrono la galleria superiore (biglietto ≈ 25 €); l’accesso turistico è chiuso durante le ore di preghiera."}},{"id":"blue","img":"assets/blue.jpg","region":"marmara","unesco":true,"name":{"it":"Moschea Blu e Sultanahmet"},"desc":{"it":"La moschea del Sultano Ahmet, coronata da sei minareti e rivestita di 20.000 piastrelle di İznik dipinte a mano, guarda Santa Sofia oltre un roseto. Intorno si stende l’antico quartiere imperiale: palazzo Topkapı, Cisterna Basilica e le 4.000 botteghe del Gran Bazar."},"loc":{"it":"Sultanahmet, Istanbul"},"best":{"it":"Tutto l’anno; al crepuscolo per le foto migliori"},"tip":{"it":"L’ingresso è gratuito al di fuori delle cinque preghiere quotidiane. Abbigliamento sobrio; all’ingresso prestano i foulard."}},{"id":"galata","img":"assets/galata.jpg","region":"marmara","unesco":false,"name":{"it":"Galata e il Bosforo"},"desc":{"it":"Attraversa il ponte di Galata tra pescatori e panini al pesce, sali sulla torre genovese del XIV secolo per un panorama a 360° e poi prendi un traghetto sullo stretto che divide l’Europa dall’Asia: la crociera di livello mondiale più economica che ci sia."},"loc":{"it":"Karaköy / Beyoğlu, Istanbul"},"best":{"it":"Tutto l’anno; il traghetto al tramonto è magico"},"tip":{"it":"Usa la Istanbulkart per traghetti, tram e metro: i traghetti di linea battono le costose crociere turistiche."}},{"id":"troy","img":"assets/troy.jpg","region":"marmara","unesco":true,"name":{"it":"Troia"},"desc":{"it":"La città leggendaria dell’Iliade di Omero, dove gli archeologi hanno trovato nove città sovrapposte in 4.000 anni. Percorri le mura antiche, posa davanti al cavallo di legno e poi approfondisci nel notevole Museo di Troia, lì accanto."},"loc":{"it":"Vicino a Çanakkale, Dardanelli"},"best":{"it":"Apr–giu e set–ott"},"tip":{"it":"Da abbinare ai campi di battaglia di Gallipoli, sull’altra sponda dello stretto, per una giornata intera di storia."}},{"id":"cappadocia","img":"assets/cappadocia.jpg","region":"central","unesco":true,"name":{"it":"Cappadocia"},"desc":{"it":"Un paesaggio vulcanico surreale di camini delle fate, chiese rupestri bizantine nascoste e intere città sotterranee. All’alba oltre cento mongolfiere scivolano sulle valli di Göreme: uno dei grandi spettacoli del viaggio."},"loc":{"it":"Göreme / Nevşehir, Anatolia centrale"},"best":{"it":"Apr–giu e set–nov per i voli"},"tip":{"it":"Prenota la mongolfiera in anticipo e tieni 2-3 mattine di margine: col vento i voli si annullano. Dormi in un hotel nella roccia."}},{"id":"pamukkale","img":"assets/pamukkale.jpg","region":"aegean","unesco":true,"name":{"it":"Pamukkale e Hierapolis"},"desc":{"it":"Il «castello di cotone»: un versante di terrazze di travertino di un bianco abbagliante, colme di acqua tiepida e minerale. Sull’altopiano sovrastante si stendono le rovine della romana Hierapolis, dove si nuota tra colonne antiche sommerse nella Piscina di Cleopatra."},"loc":{"it":"Vicino a Denizli, regione egea"},"best":{"it":"Prima mattina o ora dorata; evita il caldo di mezzogiorno"},"tip":{"it":"Sulle terrazze si va scalzi: porta una borsa per le scarpe e attenzione, la pietra scivola."}},{"id":"ephesus","img":"assets/ephesus.jpg","region":"aegean","unesco":true,"name":{"it":"Efeso"},"desc":{"it":"La città classica meglio conservata del Mediterraneo orientale. Strade di marmo passano davanti alla biblioteca di Celso a due piani, alle case romane terrazzate con affreschi intatti e a un grande teatro che ospitava 25.000 spettatori."},"loc":{"it":"Selçuk, vicino a İzmir"},"best":{"it":"Mar–mag e set–nov; la prima ora dopo l’apertura"},"tip":{"it":"Prendi una guida o un’audioguida: le pietre iniziano a parlare. Non saltare le Case a terrazza (biglietto a parte)."}},{"id":"oludeniz","img":"assets/oludeniz.jpg","region":"med","unesco":false,"name":{"it":"Ölüdeniz e Fethiye"},"desc":{"it":"Una laguna turchese immobile che si avvolge attorno a una lingua di sabbia bianca, sotto montagne coperte di pini: la spiaggia più fotografata della Turchia. I parapendii biposto decollano dal Babadağ, a 1.900 m, e scendono in spirale sulla baia; la Via Licia parte lì vicino."},"loc":{"it":"Fethiye, Costa turchese"},"best":{"it":"Mag–ott; giugno e settembre sono ideali"},"tip":{"it":"Prenota il parapendio al mattino (aria più calma) e concediti una gita in barca alla Valle delle Farfalle."}},{"id":"antalya","img":"assets/antalya.jpg","region":"med","unesco":false,"name":{"it":"Adalia (Antalya)"},"desc":{"it":"La capitale della Riviera turca: un centro storico ottomano (Kaleiçi) avvolto attorno a un porto romano, cascate che si tuffano dritte in mare e lunghe spiagge alle spalle dei monti Tauro. Perge, Aspendos e Side sono a breve distanza."},"loc":{"it":"Costa mediterranea"},"best":{"it":"Apr–giu e set–nov; si nuota fino a novembre"},"tip":{"it":"Guarda la cascata del Düden inferiore da una barca e assisti d’estate a un concerto nel teatro romano di Aspendos."}},{"id":"bodrum","img":"assets/bodrum.jpg","region":"aegean","unesco":false,"name":{"it":"Bodrum"},"desc":{"it":"Case imbiancate a calce e bouganville scendono verso una baia sorvegliata dal castello di San Pietro, sede di un museo di archeologia subacquea di livello mondiale. Qui sorgeva il Mausoleo di Alicarnasso, una delle Sette Meraviglie."},"loc":{"it":"Penisola di Bodrum, Egeo"},"best":{"it":"Mag–ott; più vivace in piena estate"},"tip":{"it":"Noleggia una gulet tradizionale per una «crociera blu» lungo la costa: vale la pena anche solo per un giorno."}},{"id":"side","img":"assets/side.jpg","region":"med","unesco":false,"name":{"it":"Side e Aspendos"},"desc":{"it":"Una città portuale greco-romana su una piccola penisola, dove le colonne di marmo del tempio di Apollo incorniciano il tramonto sul mare. Poco lontano, Aspendos conserva il teatro romano meglio preservato al mondo, dove si tengono ancora spettacoli."},"loc":{"it":"Manavgat, a est di Adalia"},"best":{"it":"Apr–giu e set–nov; il tramonto al tempio"},"tip":{"it":"Le rovine si intrecciano al paese moderno: scendi la via colonnata fino al porto antico."}},{"id":"konya","img":"assets/konya.jpg","region":"central","unesco":false,"name":{"it":"Konya e Mevlâna"},"desc":{"it":"Il cuore spirituale della Turchia, dove nel XIII secolo il poeta sufi Rumi insegnò ed è sepolto sotto una cupola di piastrelle turchesi. Il suo mausoleo-museo e l’ipnotica cerimonia del sema dei dervisci rotanti attirano pellegrini di ogni fede."},"loc":{"it":"Konya, Anatolia centrale"},"best":{"it":"Tutto l’anno; festival di Rumi a dicembre"},"tip":{"it":"Assisti a un vero sema (il sabato al Centro culturale Mevlâna) e prova l’etli ekmek, la focaccia lunga un metro di Konya."}},{"id":"gobekli","img":"assets/gobekli.jpg","region":"southeast","unesco":true,"name":{"it":"Göbekli Tepe"},"desc":{"it":"Il più antico tempio monumentale conosciuto sulla Terra, eretto da cacciatori-raccoglitori intorno al 9600 a.C., circa 6.000 anni prima di Stonehenge. Cerchi di megaliti a T incisi con volpi, avvoltoi e scorpioni stanno riscrivendo la storia della civiltà."},"loc":{"it":"Vicino a Şanlıurfa, sud-est"},"best":{"it":"Mar–mag e ott–nov; le estati sono torride"},"tip":{"it":"Da abbinare all’ottimo museo archeologico di Şanlıurfa e alle vasche delle carpe di Balıklıgöl, nel centro storico."}},{"id":"nemrut","img":"assets/nemrut.jpg","region":"southeast","unesco":true,"name":{"it":"Monte Nemrut"},"desc":{"it":"Su una vetta di 2.134 m, un re dimenticato di Commagene costruì il suo sepolcro-santuario, custodito da colossali teste di pietra di dèi e aquile. All’alba e al tramonto le statue rovesciate si accendono d’arancio sopra un mare di montagne: pura irrealtà."},"loc":{"it":"Adıyaman, Tauro orientale"},"best":{"it":"Mag–ott (strada chiusa dalla neve in inverno)"},"tip":{"it":"Sali per l’alba e porta strati caldi anche ad agosto: il vento in vetta è gelido. Fai base a Kâhta o Karadut."}},{"id":"sumela","img":"assets/sumela.jpg","region":"north","unesco":false,"name":{"it":"Monastero di Sumela"},"desc":{"it":"Un monastero greco-ortodosso fondato nel IV secolo, aggrappato in modo improbabile a una parete a strapiombo, 300 metri sopra una valle boscosa avvolta dalla nebbia. Dentro, cappelle restaurate coperte di affreschi vividi; fuori, i paesaggi più verdi del Mar Nero."},"loc":{"it":"Valle di Altındere, vicino a Trebisonda"},"best":{"it":"Mag–ott; spesso avvolto in una nebbia suggestiva"},"tip":{"it":"Da abbinare al lago alpino di Uzungöl e a una sosta çay: tutto il tè turco cresce in questa regione."}},{"id":"ani","img":"assets/ani.jpg","region":"east","unesco":true,"name":{"it":"Ani"},"desc":{"it":"Le rovine struggenti di una capitale armena medievale — la «città delle 1.001 chiese» — sparse su una steppa erbosa, all’estremo confine della Turchia. Mille anni fa rivaleggiava con Costantinopoli; oggi potresti averla quasi tutta per te."},"loc":{"it":"A 45 km da Kars, nord-est"},"best":{"it":"Mag–set; l’inverno è severo ma bello"},"tip":{"it":"Metti in conto almeno mezza giornata e scarpe comode: il sito è vastissimo. Kars è famosa per il miele e il formaggio gravyer."}},{"id":"van","img":"assets/van.jpg","region":"east","unesco":false,"name":{"it":"Lago di Van e Akdamar"},"desc":{"it":"Il lago più grande della Turchia: un vasto mare interno azzurro-soda circondato da vulcani. Una breve traversata porta all’isola di Akdamar e alla sua chiesa armena della Santa Croce, del X secolo, scolpita con vividi rilievi biblici."},"loc":{"it":"Van, estremo est"},"best":{"it":"Mag–set; mandorli in fiore ad aprile"},"tip":{"it":"Inizia la giornata con la leggendaria colazione di Van: decine di piattini di formaggi, miele e kaymak."}},{"id":"mardin","img":"assets/mardin.jpg","region":"southeast","unesco":false,"name":{"it":"Mardin"},"desc":{"it":"Case di pietra color miele scendono a gradoni su un versante che domina l’infinita pianura mesopotamica. Minareti, antichi monasteri siriaci, botteghe di filigrana d’argento e caffè nei cortili ne fanno la città più suggestiva del sud-est della Turchia."},"loc":{"it":"Anatolia sud-orientale"},"best":{"it":"Mar–mag e set–nov"},"tip":{"it":"Visita il monastero di Deyrulzafaran (dello Zafferano) nell’ora dorata e alloggia in una dimora di pietra restaurata."}},{"id":"safranbolu","img":"assets/safranbolu.jpg","region":"north","unesco":true,"name":{"it":"Safranbolu"},"desc":{"it":"Una città mercantile ottomana perfettamente conservata: dimore a graticcio, vicoli acciottolati, un caravanserraglio del XVII secolo e bazar di artigiani. Il nome viene dallo zafferano che cresce ancora nei campi intorno."},"loc":{"it":"Karabük, a ~2 h da Ankara"},"best":{"it":"Apr–ott; splendida anche sotto la neve"},"tip":{"it":"Dormi in un konak (dimora ottomana), assaggia il lokum allo zafferano e sali sulla collina di Hıdırlık per la vista sui tetti."}},{"id":"uzungol","img":"assets/uzungol.jpg","region":"north","unesco":false,"name":{"it":"Uzungöl"},"desc":{"it":"Un lago di montagna immobile a 1.090 m, con una moschea dal minareto slanciato sulla riva e boschi di abeti che salgono nella nebbia: la cartolina del Mar Nero e una fuga fresca anche in piena estate."},"loc":{"it":"Çaykara, Trebisonda"},"best":{"it":"Mag–ott; le mattine di nebbia sono magiche"},"tip":{"it":"Fermati a dormire: il lago è più quieto prima che arrivino i bus delle gite e dopo che se ne vanno."}}];
