var TIPS = [{"ico":"M2 12h20M12 2a15 15 0 0 1 0 20 15 15 0 0 1 0-20zM12 2a15 15 0 0 0 0 20","h":{"it":"Visti e ingresso"},"p":{"it":"Molte nazionalità entrano senza visto o con un e-Visa rapido dal sito ufficiale evisa.gov.tr. Verifica le regole per il tuo passaporto prima di prenotare."}},{"ico":"M12 1v22M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6","h":{"it":"Denaro"},"p":{"it":"La valuta è la lira turca (₺). Le carte si accettano quasi ovunque, ma tieni contanti per bazar, taxi e mance — e contrattare al bazar è la norma."}},{"ico":"M4 21V8l8-5 8 5v13M9 21v-6h6v6","h":{"it":"Galateo nelle moschee"},"p":{"it":"Le moschee si visitano gratuitamente fuori dagli orari di preghiera. Spalle e ginocchia coperte, scarpe all’ingresso, foulard per le donne (di solito fornito). Parla a voce bassa."}},{"ico":"M2.5 19.5L21 12 2.5 4.5l3.5 7.5-3.5 7.5zM6 12h15","h":{"it":"Spostarsi"},"p":{"it":"Le distanze sono grandi: voli interni economici (THY, Pegasus, AJet) collegano tutte le regioni, i pullman sono ottimi e i treni ad alta velocità uniscono Istanbul, Ankara e Konya."}},{"ico":"M3 11l9-8 9 8M5 9v11h14V9M9 20v-7h6v7","h":{"it":"Museum Pass"},"p":{"it":"Il Museum Pass Türkiye ufficiale (muze.gov.tr) copre centinaia di siti statali — Efeso, Göbekli Tepe, Topkapı e altri — ed evita le code ai biglietti."}},{"ico":"M18 8a6 6 0 1 1-12 0M12 14v7M8 21h8M5 8h14","h":{"it":"Cibo e cultura del tè"},"p":{"it":"Dì sì al çay — il tè è la lingua dell’ospitalità. Prova una colazione turca completa, il simit di strada, il pide, i meze in riva al mare e la baklava al pistacchio di Gaziantep."}}];
var DETAILS = {"hagia":{"long":{"it":["Si racconta che l’imperatore Giustiniano, entrando nella sua cattedrale finita nel 537, sussurrò: «Salomone, ti ho superato». Per nove secoli Santa Sofia fu il cuore pulsante della cristianità bizantina; dopo il 1453 divenne la moschea imperiale degli ottomani, che aggiunsero minareti, medaglioni calligrafici e la loggia del sultano, conservando con cura i mosaici dorati. Il risultato è un edificio in cui una Vergine musiva e i nomi dei califfi condividono la stessa cupola: nulla di simile al mondo.","All’interno la cupola di 31 metri sembra sospesa su un anello di luce — i contemporanei giuravano che pendesse dal cielo con una catena d’oro. Cerca lo scintillante mosaico della Deesis nella galleria superiore, le rune vichinghe incise su un parapetto di marmo da un mercenario annoiato mille anni fa e la «colonna dei desideri», con il foro consumato dai pollici. Vieni presto e al tramonto guarda i gabbiani girare attorno ai minareti da un caffè sui tetti."]},"getting":{"it":"Tram T1 fino alla fermata Sultanahmet; 15 min a piedi da Sirkeci. Dagli aeroporti, metro M1/M11 o bus Havaist verso la città vecchia."},"eat":{"it":"Prova le köfte nelle trattorie centenarie di via Divanyolu, poi baklava e lokum in una storica pasticceria vicino a Sirkeci."},"gallery":[{"src":"assets/g/hagia-1.jpg","cap":{"it":"L’esterno del VI secolo con i minareti ottomani"}},{"src":"assets/g/hagia-2.jpg","cap":{"it":"La facciata vista da piazza Sultanahmet"}}]},"blue":{"long":{"it":["Il sultano Ahmet I aveva solo diciannove anni quando ordinò una moschea capace di rivaleggiare con Santa Sofia, dall’altra parte della piazza. Terminata nel 1616, provocò uno scandalo alla Mecca: i suoi sei minareti eguagliavano quelli della Grande Moschea, che dovette aggiungerne un settimo. Il soprannome «Moschea Blu» nasce dall’interno — oltre 20.000 piastrelle di İznik dipinte a mano, con tulipani, garofani e cipressi, che brillano sotto 260 finestre.","La moschea è il cuore di un quartiere che fu il centro di due imperi. L’Ippodromo, davanti, conserva un obelisco egizio del 1500 a.C.; la Cisterna Basilica nasconde nel buio una foresta di 336 colonne romane illuminate dall’acqua; il palazzo Topkapı distende cortili, harem e tesoro sulla punta della penisola; e il Gran Bazar — 4.000 botteghe sotto volte dipinte — contratta dal 1461. A Sultanahmet dedica almeno due giornate intere."]},"getting":{"it":"Tram T1 fino a Sultanahmet; tutto il quartiere si gira a piedi. Ingresso gratuito fuori dalle cinque preghiere, abbigliamento sobrio."},"eat":{"it":"Infilati in un çay bahçesi (giardino da tè) in un cortile tra le due grandi moschee: sahlep d’inverno, succo di melagrana spremuto d’estate."},"gallery":[{"src":"assets/g/blue-1.jpg","cap":{"it":"Un soffitto di blu di İznik dipinto a mano"}},{"src":"assets/g/blue-2.jpg","cap":{"it":"Il grande cortile nell’ora tranquilla"}},{"src":"assets/g/blue-3.jpg","cap":{"it":"La Cisterna Basilica, a cinque minuti a piedi"}}]},"galata":{"long":{"it":["Karaköy e Galata erano il quartiere portuale dei mercanti genovesi, e la loro torre di guardia del 1348 domina ancora lo skyline a nord del Corno d’Oro. Salici (c’è l’ascensore) per la classica vista a 360°: da un lato le cupole della città vecchia, dall’altro il Bosforo che piega verso il Mar Nero. Sotto, vicoli ripidi pieni di gallerie, torrefazioni e antiquari precipitano verso l’acqua passando davanti alla medievale moschea Arap.","Poi concediti la cosa più bella e più economica di Istanbul: un traghetto di linea. La traversata per Kadıköy, o il giro completo del Bosforo, scivola davanti a palazzi ottomani, yalı di legno e alla Torre della Fanciulla, con il çay servito in coperta per pochi spiccioli. Torna sul ponte di Galata al tramonto, quando i pescatori riempiono i parapetti e sotto le barche dei panini al pesce accendono le griglie."]},"getting":{"it":"Metro M2 fino a Şişhane, tram T1 fino a Karaköy, oppure la storica funicolare del Tünel: la seconda metropolitana più antica al mondo, in servizio dal 1875."},"eat":{"it":"Balık ekmek (panino con pesce grigliato) vicino al ponte, künefe nelle pasticcerie di Karaköy e caffè di terza onda su per la salita, a Galata."},"gallery":[{"src":"assets/g/galata-1.jpg","cap":{"it":"La torre genovese sopra i tetti di Galata"}}]},"troy":{"long":{"it":["Per secoli gli studiosi liquidarono Troia come pura poesia — finché negli anni 1870 Heinrich Schliemann scavò la collina di Hisarlık e trovò non una città ma nove, sovrapposte come le pagine di un libro lungo 4.000 anni. Lo strato noto come Troia VII, distrutto dal fuoco intorno al 1180 a.C., è il candidato migliore per la guerra di Omero. Si seguono ancora le mura inclinate che avrebbero resistito dieci anni ai Greci, si sale la rampa dove passavano i carri, si sta nel santuario dove si facevano offerte mille anni prima di Roma.","Il sito premia l’immaginazione, e il pluripremiato Museo di Troia lì accanto la alimenta: quattro piani di ori, armi e sarcofagi raccontano la storia meglio di qualsiasi guida. Il gigantesco cavallo di legno all’ingresso è puro teatro — sali lo stesso. Oltre i Dardanelli si stendono i campi di battaglia di Gallipoli del 1915: un pomeriggio commovente che chiude 3.000 anni di guerre attorno agli stessi stretti."]},"getting":{"it":"30 min in auto o minibus da Çanakkale (volo da Istanbul, oppure 5-6 h in bus/auto via il ponte di Gallipoli)."},"eat":{"it":"Il lungomare di Çanakkale serve ottime sardine alla griglia e il peynir helvası, l’halva locale al formaggio: provali entrambi dopo le rovine."},"gallery":[{"src":"assets/g/troy-1.jpg","cap":{"it":"Il cavallo di legno sul lungomare di Çanakkale"}},{"src":"assets/g/troy-2.jpg","cap":{"it":"Nove città in un solo tumulo, a Hisarlık"}}]},"ephesus":{"long":{"it":["Efeso era la New York dell’Oriente romano: una metropoli portuale di 200.000 abitanti dove il tempio di Artemide — una delle Sette Meraviglie — attirava pellegrini da tutto il Mediterraneo. San Paolo vi predicò (scatenando una rivolta) nel grande teatro; si crede che la Vergine Maria abbia trascorso gli ultimi anni in una casetta di pietra sulla collina sopra la città. Ciò che resta è sbalorditivo: viali di marmo solcati dalle ruote dei carri, la facciata a due piani di una biblioteca che custodiva 12.000 rotoli, latrine pubbliche, un lupanare e persino inserzioni incise nella pavimentazione.","Non saltare le Case a terrazza sotto la copertura protettiva: dimore romane con pavimenti a mosaico, pareti affrescate e riscaldamento a pavimento, abbandonate a metà ristrutturazione nel III secolo, come se i pittori se ne fossero appena andati. Vieni all’apertura o nel tardo pomeriggio: a metà giornata i gruppi delle navi da crociera invadono il sito e d’estate il marmo restituisce un caldo serio."]},"getting":{"it":"A 3 km da Selçuk: in taxi, in dolmuş o anche a piedi. Selçuk dista 1 h di treno o auto dall’aeroporto di İzmir."},"eat":{"it":"Şirince, borgo collinare di vecchie case greche a 8 km, è il posto per un lungo pranzo: colazione di campagna, gözleme e vini di frutta."},"gallery":[{"src":"assets/g/ephesus-1.jpg","cap":{"it":"Il Grande Teatro, da 25.000 posti"}},{"src":"assets/g/ephesus-2.jpg","cap":{"it":"Il tempio di Adriano, sulla via dei Cureti"}}]},"pamukkale":{"long":{"it":["Diciassette sorgenti calde sature di calcio scendono su questo versante da due milioni di anni, lasciando una cascata pietrificata di terrazze di un bianco abbagliante: il «castello di cotone». I Romani, che non sprecavano mai un bagno caldo, costruirono sull’altopiano la città termale di Hierapolis; si veniva da tutto l’impero a prendere le acque e in molti vi rimasero per sempre — ecco perché la necropoli è una delle più vaste dell’Anatolia antica.","Sali scalzo tra le vasche azzurre e poco profonde (scarpe in mano: è la regola che mantiene bianco il travertino), poi esplora Hierapolis: un teatro splendidamente ripido, il martyrium di san Filippo e la Piscina Antica, dove si nuota in acqua tiepida e frizzante sopra colonne di marmo rovesciate. Nell’ora dorata l’intero versante diventa rosa — gli escursionisti se ne sono andati e le terrazze sembrano davvero irreali."]},"getting":{"it":"20 min da Denizli con dolmuş frequenti; Denizli ha un aeroporto (DNZ) e treni veloci da İzmir. Molti lo abbinano a Efeso."},"eat":{"it":"Il villaggio di Pamukkale offre un generoso köy kahvaltısı (colazione di campagna) con miele locale; Denizli è nota per l’agnello tandır a cottura lenta."},"gallery":[{"src":"assets/g/pamukkale-1.jpg","cap":{"it":"Le vasche a terrazza sul bordo del travertino"}},{"src":"assets/g/pamukkale-2.jpg","cap":{"it":"Il versante bianco visto dal fondovalle"}}]},"bodrum":{"long":{"it":["L’antica Alicarnasso ha dato al mondo due meraviglie: lo storico Erodoto e il Mausoleo del re Mausolo, tomba così grandiosa da diventare una Meraviglia del mondo — e la parola stessa con cui da allora si indica ogni sepolcro monumentale. Le sue pietre furono poi riutilizzate dai Cavalieri di San Giovanni per il castello di San Pietro, che oggi domina il porto e ospita il Museo di Archeologia Subacquea: relitti dell’età del bronzo, carichi di vetro e l’oro di una principessa micenea, tutti recuperati dal fondo dell’Egeo.","La Bodrum di oggi è la Saint-Tropez turca: case cubiche imbiancate sotto le bouganville, un porto turistico di super-yacht e gulet di legno, mandarineti, beach club e una vita notturna famosamente tarda. La penisola nasconde angoli più quieti: i tavoli di pesce sull’acqua a Gümüşlük, le baie da windsurf di Bitez, le rovine di pietra di Sandima in collina. La mossa classica resta la «crociera blu»: giorni di navigazione tra calette deserte, dove l’unica decisione è quando tuffarsi."]},"getting":{"it":"Volo su Milas-Bodrum (BJV), a 40 min dal centro; gli autobus collegano tutta la costa egea. In stagione traghetti per Kos e Rodi."},"eat":{"it":"Pesce e meze al tramonto a Gümüşlük, dolci al mandarino ovunque — quelli della penisola sono famosi — e lokma vicino al porto turistico."},"gallery":[{"src":"assets/g/bodrum-1.jpg","cap":{"it":"Gulet e yacht nel porto di Bodrum"}},{"src":"assets/g/bodrum-2.jpg","cap":{"it":"Un porticciolo tranquillo sulla penisola"}}]},"oludeniz":{"long":{"it":["Ölüdeniz significa «mare morto»: non per il sale, ma perché la laguna resta liscia come uno specchio anche quando la tempesta agita il Mediterraneo oltre il cordone di sabbia. Protetta come parco naturale, è il punto più fotografato della costa turca: una curva di sabbia bianca e pini attorno a un’acqua che passa dal giada allo zaffiro profondo. Arriva presto — la luce è la migliore e prima delle dieci la lingua di sabbia è ancora vuota.","Il paese sopra la baia è anche uno dei grandi centri mondiali del parapendio. I piloti biposto decollano dal Babadağ, a 1.900 metri, e impiegano mezz’ora a scendere in spirale sulla laguna; non serve esperienza, solo fegato nella rincorsa. Dalla spiaggia partono barche per la Valle delle Farfalle, una comunità in un canyon raggiungibile solo dal mare, e la Via Licia — il sentiero a lunga percorrenza più celebre della Turchia — inizia i suoi 540 km poco più su, a Ovacık."]},"getting":{"it":"25 min in dolmuş da Fethiye; l’aeroporto più vicino è Dalaman (DLM), a 1 h con navette."},"eat":{"it":"Al mercato del pesce di Fethiye compri il pescato e i locali intorno te lo cucinano; chiudi con un gelato sul lungomare."},"gallery":[{"src":"assets/g/oludeniz-1.jpg","cap":{"it":"La laguna e la sua famosa lingua di sabbia"}}]},"antalya":{"long":{"it":["Fondata verso il 150 a.C. da un re di Pergamo, Adalia accoglie visitatori da sempre: per la visita di Adriano, nel 130 d.C., ricevette una porta di marmo a tre fornici, ancora oggi l’ingresso più solenne a Kaleiçi, il centro storico fortificato. Dentro è un labirinto di dimore ottomane, cortili profumati di mandarino e un minareto scanalato del XIII secolo, tutto raccolto attorno a un minuscolo porto romano scavato nella roccia.","La città è anche la porta dei siti antichi della Panfilia — le vie colonnate di Perge, il teatro di Aspendos, i templi sul mare di Side — e di una costa che va dalle cascate del Düden, che precipitano dalla scogliera, al lungo arco di ciottoli di Konyaaltı sotto i monti Tauro. La stagione balneare va da aprile a novembre e d’inverno si può sciare a Saklıkent al mattino e fare un bagno (coraggioso) dopo pranzo."]},"getting":{"it":"L’aeroporto di Adalia (AYT) riceve voli diretti da tutta Europa; tram fino al centro storico in 40 min. Perge e Aspendos sono gite di mezza giornata."},"eat":{"it":"Il piyaz (insalata di fagioli bianchi con tahina) è il piatto simbolo di Adalia; mangialo con le köfte nel quartiere del bazar, poi una spremuta d’arancia coltivata in città."},"gallery":[{"src":"assets/g/antalya-1.jpg","cap":{"it":"Il teatro romano di Aspendos, breve gita a est"}}]},"side":{"long":{"it":["Side fu il grande porto della Panfilia: mercato di schiavi, covo di pirati e, in età romana, città abbastanza ricca da lastricare di marmo la via principale e fiancheggiarla di colonnati. Si dice che qui si siano incontrati Cleopatra e Marco Antonio. Le rovine non furono mai abbandonate: nell’Ottocento vi crebbe dentro un villaggio di pescatori, così oggi si passa davanti a un teatro da 15.000 posti e a una basilica bizantina per arrivare ai giardini delle pensioni e ai bar sulla spiaggia.","Sulla punta estrema della penisola, cinque colonne rialzate del tempio di Apollo incorniciano il mare: al tramonto è la veduta più romantica di tutto il Mediterraneo turco. A venti minuti nell’entroterra, il teatro di Aspendos è il meglio conservato del mondo romano, con l’edificio scenico ancora intatto per tutte le 41 file di gradini; se puoi, assisti lì a un’opera o a un balletto in una notte d’estate."]},"getting":{"it":"A 75 km a est dell’aeroporto di Adalia; autobus e dolmuş passano da Manavgat. Aspendos e le cascate di Manavgat sono lungo la strada."},"eat":{"it":"Ristoranti di pesce circondano il porto antico sotto il tempio; nell’entroterra Manavgat è nota per la trota di fiume alla griglia e gli spiedini çöp şiş."},"gallery":[{"src":"assets/g/side-1.jpg","cap":{"it":"Le colonne di Apollo sulla punta della penisola"}},{"src":"assets/g/side-2.jpg","cap":{"it":"Aspendos: il teatro meglio conservato del mondo romano"}}]},"cappadocia":{"long":{"it":["Tre vulcani seppellirono questo altopiano sotto la cenere milioni di anni fa; vento e pioggia scolpirono poi il tufo tenero in minareti, funghi e «camini delle fate», e gli uomini completarono l’opera scavando case, colombaie, monasteri e intere città sotterranee profonde fino a otto livelli, dove i primi cristiani potevano nascondersi con bestiame, torchi e cappelle. Al Museo all’aperto di Göreme, affreschi dell’XI secolo ardono ancora dentro le chiese rupestri.","Quasi tutti volano: nelle mattine senza vento più di cento mongolfiere si alzano all’alba sopra le valli, uno dei grandi spettacoli del viaggio. Scegli un operatore autorizzato, tieni mattine di riserva in caso di vento e dedica il resto dei giorni a camminare nella Valle delle Rose e nelle gole di Ihlara, a visitare le città sotterranee di Kaymaklı o Derinkuyu e a dormire in un hotel nella roccia: le stanze restano naturalmente fresche per tutta l’estate."]},"getting":{"it":"Volo su Nevşehir (NAV) o Kayseri (ASR), entrambi a meno di 1 h da Göreme in navetta. Gli autobus notturni da Istanbul impiegano circa 11 h."},"eat":{"it":"Il testi kebab — carne cotta a lungo in un’anfora di argilla sigillata, spaccata al tavolo — con i vini locali Emir e Kalecik Karası, da suolo vulcanico."},"gallery":[{"src":"assets/g/cappadocia-1.jpg","cap":{"it":"Decollo all’alba sopra Göreme"}},{"src":"assets/g/cappadocia-2.jpg","cap":{"it":"Le valli dalla cesta di una mongolfiera"}},{"src":"assets/g/cappadocia-3.jpg","cap":{"it":"Le chiese rupestri del parco nazionale di Göreme"}}]},"konya":{"long":{"it":["«Vieni, vieni, chiunque tu sia»: l’invito attribuito a Jalāl al-Dīn Rumi, mistico e poeta sufi del XIII secolo, definisce ancora la sua città. Konya era la capitale dei sultani selgiuchidi quando la famiglia di Rumi vi giunse in fuga dai mongoli, e la loro architettura migliore è sopravvissuta: il santuario dalla cupola turchese dove riposa, le madrase İnce Minareli e Karatay con le volte di piastrelle trapunte di stelle, e la moschea Alaeddin sul suo antico tumulo.","I seguaci di Rumi fondarono l’ordine mevlevi — i dervisci rotanti — la cui cerimonia del sema trasforma il lutto in una lenta meditazione roteante. Assisti a una autentica il sabato sera al Centro culturale Mevlâna (è un atto di culto, non uno spettacolo: non si applaude). A dicembre torna lo Şeb-i Arus, anniversario della «notte di nozze» di Rumi con il divino, quando pellegrini e lettori di poesia riempiono la città. La Konya di oggi è devota, prospera e tranquilla: la Turchia più serena."]},"getting":{"it":"I treni ad alta velocità raggiungono Konya in ~2 h da Ankara e ~4 h 30 da Istanbul; l’aeroporto (KYA) ha voli giornalieri per Istanbul."},"eat":{"it":"L’etli ekmek — un metro di focaccia sottile con agnello speziato — con il fırın kebabı (montone al forno) e la zuppa di okra, classico dei matrimoni di Konya."},"gallery":[{"src":"assets/g/konya-1.jpg","cap":{"it":"Il sema: preghiera in movimento"}},{"src":"assets/g/konya-2.jpg","cap":{"it":"Il mausoleo di Rumi con le piastrelle turchesi"}}]},"sumela":{"long":{"it":["La leggenda vuole che due monaci ateniesi, guidati da una visione della Vergine, fondassero Sumela nel 386 su una cengia che nessun costruttore assennato avrebbe scelto: una parete a picco, 300 metri sopra la valle di Altındere. Ciò che vi crebbe in sedici secoli — cappelle, cucine, celle, una sorgente sacra e una biblioteca — si aggrappa alla roccia come un nido di rondine, e la sua chiesa rupestre risplende di affreschi di profeti, apostoli e imperatori bizantini, sovrapposti da generazioni di pittori.","Il monastero si svuotò nel 1923 con lo scambio di popolazioni, ma il restauro ha riportato in vita gli affreschi. Metà dell’esperienza è l’ambiente: la salita tra faggi e pini, le nuvole che scorrono sotto gli edifici, il rombo del torrente molto più in basso. Questa è la Turchia verde, umida e alpina: abbinala alle terrazze di tè di Rize e al lago di montagna di Uzungöl per un giro completo del Mar Nero."]},"getting":{"it":"A 45 km da Trebisonda (aeroporto TZX); tour e dolmuş ogni giorno. Una navetta copre l’ultima salita dal parcheggio della valle."},"eat":{"it":"I classici del Mar Nero: muhlama (fonduta di farina di mais e formaggio), acciughe fresche in stagione e Laz böreği come dolce, con tè di Rize a volontà."},"gallery":[{"src":"assets/g/sumela-1.jpg","cap":{"it":"Il monastero dalla strada della valle"}},{"src":"assets/g/sumela-2.jpg","cap":{"it":"Le pareti boscose del parco nazionale di Altındere"}}]},"safranbolu":{"long":{"it":["Safranbolu si arricchì grazie a due cose: lo zafferano dei campi circostanti, ancora tra le spezie più preziose al mondo, e la sua posizione sulla via carovaniera ottomana da Istanbul al Mar Nero. I mercanti riversarono le loro fortune in circa 2.000 konak a graticcio — tre piani, piani superiori aggettanti, soffitti intagliati, vasche interne per rinfrescare — e poiché il Novecento aggirò la città, quasi tutto è sopravvissuto intatto, valendole l’iscrizione UNESCO nel 1994.","Per l’effetto pieno, dormi in un konak restaurato: assi che scricchiolano, porte basse, colazione in un cortile ombroso. Passeggia sotto il portico artigiano degli Yemeniciler, bevi un caffè nel caravanserraglio Cinci Han del Seicento, sali sulla collina di Hıdırlık per il classico panorama di tetti rossi e compra lokum allo zafferano da famiglie che coltivano i crochi da generazioni. D’inverno la neve sui tetti la trasforma in una fiaba."]},"getting":{"it":"~2 h in auto o autobus da Ankara, 5 h da Istanbul; gli autobus arrivano a Kıranköy, poco sopra il quartiere storico di Çarşı."},"eat":{"it":"Lokum e tè allo zafferano, kuyu kebabı (agnello arrostito in fossa) e la pasta bükme, poi un caffè turco nel cortile di un caravanserraglio."},"gallery":[{"src":"assets/g/safranbolu-1.jpg","cap":{"it":"Konak lungo un vicolo acciottolato"}},{"src":"assets/g/safranbolu-2.jpg","cap":{"it":"La torre dell’orologio sopra il centro storico"}}]},"uzungol":{"long":{"it":["Secoli fa una frana sbarrò il torrente Haldizen e lasciò Uzungöl — il «lago lungo» — un nastro d’acqua verde sul fondo di una ripida valle alpina, con un villaggio e una moschea dal minareto slanciato sulla riva e boschi di abeti che salgono nella nebbia da ogni lato. A 1.090 metri l’aria resta fresca anche ad agosto, e la scena somiglia più alle Alpi o al Caucaso che all’idea che si ha della Turchia.","Il giro pianeggiante sulla riva si percorre in meno di un’ora; poi sali: le strade delle yayla (pascoli d’alta quota) portano a Şekersu e oltre, dove i pastori passano l’estate e le nuvole restano sotto di te. Il villaggio è una base comoda per tutta la regione: monastero di Sumela, altopiano di Ayder e il paese del tè di Rize sono tutti a portata di gita. Se puoi, vieni infrasettimanale o fuori stagione: i weekend estivi sono vivaci e rumorosi."]},"getting":{"it":"99 km dall’aeroporto di Trebisonda via Of e la valle di Solaklı: circa 1 h 30 in auto, minibus o con tour giornalieri."},"eat":{"it":"Trota fresca degli allevamenti del lago, muhlama che sfrigola nel tegame di rame, burro e miele locali a colazione: la cucina di montagna al suo meglio."},"gallery":[{"src":"assets/g/uzungol-1.jpg","cap":{"it":"La moschea sulla riva del lago, nella sua valle"}},{"src":"assets/g/uzungol-2.jpg","cap":{"it":"La vista dalla terrazza panoramica"}}]},"ani":{"long":{"it":["Intorno all’anno 1000 Ani contava forse 100.000 abitanti e commerciava sulla via della Seta alla pari con Costantinopoli e Il Cairo. Capitale del regno armeno dei Bagratidi, era così costellata di santuari che i cronisti la chiamavano la città delle 1.001 chiese. Poi vennero le conquiste — bizantina, selgiuchide, mongola — un terremoto nel 1319, lo spostamento delle rotte commerciali e infine il silenzio. Ciò che resta si erge solitario su un altopiano erboso cinto dalle gole dell’Akhurian, proprio sul confine con l’Armenia.","Si vaga di rovina in rovina con le allodole per compagnia: la cattedrale il cui architetto riparò anche la cupola di Santa Sofia, la chiesa rotonda di San Gregorio affrescata da terra a soffitto, un palazzo selgiuchide, una moschea affacciata sulla gola, i resti di un ponte di 1.600 anni fa. Pochi luoghi al mondo sono così carichi di grandezza scomparsa. Porta acqua e protezione dal sole e metti in conto almeno mezza giornata; abbinala all’architettura in pietra di Kars, di aria baltica, e alle sue celebri colazioni di miele e formaggio."]},"getting":{"it":"A 45 km a est di Kars (aeroporto KSY, voli da Istanbul e Ankara); taxi e piccoli tour fanno il tragitto, oppure guida tu sulle strade deserte della steppa."},"eat":{"it":"Kars è la capitale casearia della Turchia: gravyer stagionato, miele dei pascoli di montagna e, d’inverno, oca arrostita alla maniera locale."},"gallery":[{"src":"assets/g/ani-1.jpg","cap":{"it":"La chiesa di San Gregorio sopra la gola"}},{"src":"assets/g/ani-2.jpg","cap":{"it":"Affreschi medievali dentro la chiesa di Tigran Honents"}}]},"van":{"long":{"it":["Il lago di Van è un mare interno sette volte il Lemano, con acqua alcalina così ricca di minerali che ci si può lavare i panni — e nuotarci, galleggiando, per tutta l’estate. Sulle sue rive sorse e cadde il regno di Urartu, nell’età del ferro; la loro cittadella del IX secolo a.C., il castello di Van, si allunga ancora su una cresta rocciosa sopra la città moderna, con iscrizioni cuneiformi incise nella parete.","Il gioiello del lago è l’isola di Akdamar, dove la chiesa armena della Santa Croce, del X secolo, porta la Bibbia all’esterno: Giona e la balena, Davide e Golia, Adamo ed Eva, tutti scolpiti a rilievo su pietra rosata, con sullo sfondo il monte Süphan innevato. I traghetti fanno la traversata di 20 minuti tutto il giorno. In città cerca i celebri gatti di Van, nuotatori e vaporosi — un occhio azzurro, uno ambra — e dedica un’intera mattina alla colazione di Van, un’istituzione da quaranta piattini."]},"getting":{"it":"L’aeroporto di Van (VAN) ha voli diretti da Istanbul e Ankara. I traghetti per Akdamar partono da Gevaş, 45 km a sud-ovest della città."},"eat":{"it":"La colazione di Van: otlu peynir (formaggio alle erbe), kaymak con miele, murtuğa e tè infinito, più il pesce del lago, il muggine perlato, alla griglia."},"gallery":[{"src":"assets/g/van-1.jpg","cap":{"it":"L’isola di Akdamar e la chiesa della Santa Croce"}},{"src":"assets/g/van-2.jpg","cap":{"it":"I rilievi biblici sulle pareti della chiesa"}}]},"gobekli":{"long":{"it":["Göbekli Tepe ha riscritto la storia umana. Verso il 9600 a.C. — prima dell’agricoltura, della ceramica e della ruota — cacciatori-raccoglitori trascinarono su questa collina pilastri di calcare da 10 tonnellate ed eressero cerchi di megaliti scolpiti: volpi, gru, scorpioni, serpenti e leopardi in agguato, con braccia e mani ripiegate sulle pietre a T come se fossero esseri viventi. Gli archeologi hanno a lungo supposto che la religione venisse dopo la sedentarizzazione; qui, a quanto pare, il tempio venne prima e i villaggi nacquero per servirlo.","È stata scavata solo una frazione — la geofisica indica almeno altri quindici cerchi ancora sepolti — quindi state guardando il bordo visibile di qualcosa di molto più grande. Passerelle girano attorno al recinto principale sotto la copertura; vieni presto o tardi per la luce morbida e poca folla. Poi, a Şanlıurfa, l’ottimo museo archeologico custodisce i reperti (compresa la più antica statua umana a grandezza naturale) e le vasche sacre delle carpe di Balıklıgöl brillano al tramonto. Karahan Tepe, sito gemello dall’aria ancora più antica, è a un’ora di strada."]},"getting":{"it":"A 22 km da Şanlıurfa (aeroporto GNY); taxi, tour e una navetta dal museo ogni giorno. Vieni presto: il caldo estivo è feroce."},"eat":{"it":"Urfa è un pellegrinaggio gastronomico a sé: çiğ köfte fatto alla maniera originale, lahmacun dal forno a legna, peperoncino isot ovunque e künefe per chiudere."},"gallery":[{"src":"assets/g/gobekli-1.jpg","cap":{"it":"I pilastri a T del recinto C"}},{"src":"assets/g/gobekli-2.jpg","cap":{"it":"Il bestiario inciso della Pietra dell’Avvoltoio"}}]},"nemrut":{"long":{"it":["Antioco I di Commagene governava un piccolo regno cuscinetto tra Roma e la Persia — e decise di essere ricordato come nessuno dei due. Sulla sua montagna più alta fece innalzare un tumulo funerario di 50 metri in pietrisco, affiancato da terrazze dove si fece intronizzare accanto a Zeus, Apollo ed Eracle: un dio autoproclamato, di una stirpe che faceva risalire sia ad Alessandro sia a Dario. I terremoti hanno fatto cadere le teste dai corpi di nove metri, ed è proprio quell’immagine che tutti vengono a cercare: volti di pietra colossali che guardano sereni un mare di montagne.","Il rito è il punto: salire al buio, percorrere gli ultimi 600 metri di sentiero e guardare l’alba incendiare la terrazza est (o il tramonto quella ovest). Anche ad agosto porta una giacca vera: il vento in vetta morde. La sua camera sepolcrale, nel cuore del tumulo, non è mai stata trovata. Scendendo, fermati al ponte romano di Cendere e al tumulo di Karakuş, e pensa Nemrut e Şanlıurfa come un unico itinerario con Göbekli Tepe."]},"getting":{"it":"Fai base a Kâhta o nel villaggio di Karadut (aeroporto di Adıyaman a 1 h 30); la strada è aperta grosso modo da maggio a ottobre."},"eat":{"it":"Le pensioni di Karadut preparano cene casalinghe per chi parte all’alba; tornato ad Adıyaman, prova il çiğ köfte e i dolci ricchi di pistacchio."},"gallery":[{"src":"assets/g/nemrut-1.jpg","cap":{"it":"L’alba sulla terrazza est"}},{"src":"assets/g/nemrut-2.jpg","cap":{"it":"Le teste degli dèi ai piedi del loro re"}}]},"mardin":{"long":{"it":["Mardin scende lungo un versante in gradoni di calcare color miele, con ogni tetto che diventa una terrazza affacciata sulla pianura mesopotamica, verso la Siria: al crepuscolo la vista si dissolve semplicemente in una foschia dorata. Arabi, curdi, turchi, cristiani siriaci e un tempo una grande comunità ebraica hanno costruito insieme questa città, e si vede: minareti e campanili si dividono lo skyline e nei vicoli del bazar, larghi quanto un asino, si sentono cinque lingue.","La gloria di Mardin è la pietra scolpita: alza lo sguardo verso i portali, le madrase Zinciriye e Kasımiye, il minareto scanalato della Grande Moschea. Appena fuori città, il monastero di Deyrulzafaran, color zafferano, celebra in aramaico — la lingua di Gesù — dal V secolo; più addentro nell’altopiano del Tur Abdin, Mor Gabriel è uno dei monasteri attivi più antichi del mondo. Compra argento in filigrana (telkari), assaggia l’amaro caffè mırra e dormi in una dimora di pietra con la pianura sotto la finestra."]},"getting":{"it":"L’aeroporto di Mardin (MQM) dista 20 min dal centro storico; gli autobus collegano Şanlıurfa (3 h) e Diyarbakır (1 h 30) per un giro del sud-est."},"eat":{"it":"Kaburga dolması (costine d’agnello ripiene di riso), kebab alle ciliegie, dolcetti alle mandorle e l’amaro caffè mırra versato da un bricco d’ottone."},"gallery":[{"src":"assets/g/mardin-1.jpg","cap":{"it":"Dimore di pietra a terrazze sopra la pianura"}},{"src":"assets/g/mardin-2.jpg","cap":{"it":"Facciate scolpite del centro storico"}}]}};
var UZUNGOL = {"id":"uzungol","img":"assets/uzungol.jpg","region":"north","unesco":false,"name":{"it":"Uzungöl"},"desc":{"it":"Un lago di montagna immobile a 1.090 m, con una moschea dal minareto slanciato sulla riva e boschi di abeti che salgono nella nebbia: la cartolina del Mar Nero e una fuga fresca anche in piena estate."},"loc":{"it":"Çaykara, Trebisonda"},"best":{"it":"Mag–ott; le mattine di nebbia sono magiche"},"tip":{"it":"Fermati a dormire: il lago è più quieto prima che arrivino i bus delle gite e dopo che se ne vanno."}};
